import type { ReactNode } from 'react';
import { illustrations, type IllustrationName } from './illustrations';
import './empty-states.css';

export interface EmptyStateProps {
  illustration: IllustrationName;
  /** What is empty, said plainly: "No anchorages saved". */
  title: string;
  /** What to do next. */
  description?: ReactNode;
  /** A next step, such as a button. */
  action?: ReactNode;
  /** Heading level for the title, so it fits the page outline. */
  headingLevel?: 2 | 3 | 4;
  className?: string;
}

/** An empty screen that says what is missing and what to do, with an original illustration. */
export function EmptyState({
  illustration,
  title,
  description,
  action,
  headingLevel = 3,
  className,
}: EmptyStateProps) {
  const Heading = `h${headingLevel}` as const;
  return (
    <div className={['atl-empty', className].filter(Boolean).join(' ')}>
      <svg className="atl-empty__art" viewBox="0 0 160 120" aria-hidden="true">
        {illustrations[illustration]}
      </svg>
      <Heading className="atl-empty__title">{title}</Heading>
      {description ? <p className="atl-empty__description">{description}</p> : null}
      {action ? <div className="atl-empty__action">{action}</div> : null}
    </div>
  );
}

@layer atlas.components {
  .atl-empty {
    display: grid;
    justify-items: center;
    gap: var(--space-xs);
    max-width: 26rem;
    padding: var(--space-l);
    text-align: center;
  }

  .atl-empty__art {
    width: min(12rem, 70%);
    height: auto;
    margin-bottom: var(--space-xs);
    color: var(--ink-soft);
    fill: none;
    stroke: currentColor;
    stroke-width: 1.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .atl-empty__art .sea {
    stroke: var(--isobath);
  }

  .atl-empty__art .dash {
    stroke-dasharray: 3 4;
  }

  .atl-empty__art .mark {
    fill: var(--ink);
    stroke: none;
  }

  .atl-empty__art .mark-fill {
    fill: var(--ink-soft);
  }

  .atl-empty__title {
    font-size: var(--step-1);
    font-weight: 650;
  }

  .atl-empty__description {
    color: var(--ink-soft);
    font-family: var(--font-prose);
    text-wrap: balance;
  }

  .atl-empty__action {
    margin-top: var(--space-xs);
  }
}

export { EmptyState } from './EmptyState';
export type { EmptyStateProps } from './EmptyState';
export { illustrations } from './illustrations';
export type { IllustrationName } from './illustrations';
